 "content": "def transform(grid):
    """Fill single-cell gaps between repeated markers with color 2."""
    from collections import Counter

    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker_colors = {v for row in grid for v in row if v != bg}
    if not marker_colors:
        return out
    marker = next(iter(marker_colors))
    for r, row in enumerate(grid):
        positions = [c for c, value in enumerate(row) if value == marker]
        for a, b in zip(positions, positions[1:]):
            if b - a == 2 and row[a + 1] == bg:
                out[r][a + 1] = 2
    return out
